    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> BlockMessageSenderFromRepliesAsync(long messageId = default, bool deleteMessage = default, bool deleteAllMessages = default, bool reportSpam = default)
    {

           using var activity =  StartCallActivity("BlockMessageSenderFromRepliesAsync", typeof(BlockMessageSenderFromReplies).FullName ?? "BlockMessageSenderFromRepliesAsync");

           try
           {
             return client.BlockMessageSenderFromRepliesAsync(messageId, deleteMessage, deleteAllMessages, reportSpam);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
